            var c = tc ? parseInt(tc, 10) : paid;
            if (!isFinite(c)) {
                c = paid;
            }
            var lines = _bcmApproxGenerationLines(c);
            wrap.textContent = '';
            if (!lines.image) {
                continue;
            }
            var d1 = document.createElement('div');
            d1.className = 'bcm-package-gens-line';
            d1.textContent = lines.image;
            wrap.appendChild(d1);
        }
    }

    function _bcmUpdateCustomGenEstimate(credits) {
        var el = by_id('bcm_custom_gen_estimate');
        if (!el) {
            return;
        }
        var lines = _bcmApproxGenerationLines(credits);
        el.textContent = '';
        if (!lines.image) {
            el.hidden = true;
            return;
        }
        el.hidden = false;
        var r1 = document.createElement('div');
        r1.className = 'bcm-custom-gen-line';
        r1.textContent = lines.image;
        el.appendChild(r1);
    }

