    window._bcmPaidCreditsForPurchase = function() {
        var modal = by_id('buy_credits_modal');
        var inp = by_id('bcm_credits_input');
        if (!inp) {
            return 0;
        }
        if (modal) {
            var sel = modal.querySelector('.bcm-package.selected');
            if (sel) {
                var p = parseInt(sel.dataset.credits, 10);
                if (isFinite(p) && p > 0) {
                    return p;
