    // #ctrl_center is absolutely centered on the viewport, so the side columns slide underneath
    // it once the right block gets wide (long name + credits pill). Measure the natural widths
    // first and drop optional chrome until the centered block clears both sides, instead of
    // trimming at a fixed breakpoint that would also hit users who have the room.
    function fit_ctrl_bar(){
        const ctrl_left = by_id('ctrl_left');
        const ctrl_right = by_id('ctrl_right');
        const ctrl_center = by_id('ctrl_center');
        if (!ctrl_left || !ctrl_right || !ctrl_center) {
            return;
        }
        // Expanded search is a fixed overlay on top of the bar, not part of its layout.
        if (ctrl_center.classList.contains('cmdk')) {
            return;
        }

        // Reset before measuring: reading an already-forced ctrl_right would add another 25px
        // to min_width on every call.
        document.body.classList.remove('ctrl_tight');
        document.body.classList.remove('ctrl_tighter');
        document.body.classList.remove('ctrl_tightest');
        ctrl_left.style.width = '';
        ctrl_left.style.minWidth = '';
        ctrl_right.style.width = '';
        ctrl_right.style.minWidth = '';

        // Cheapest first: the credits pill duplicates a dropdown row and the admin icons are
        // secondary, the username only loses characters, and the history button goes last.
        const trim_steps = ['ctrl_tight', 'ctrl_tighter', 'ctrl_tightest'];
        let room = Math.floor((window.innerWidth - ctrl_center.offsetWidth) / 2) - 10;
        for (let i = 0; i < trim_steps.length; i++) {
            if (Math.max(ctrl_left.offsetWidth, ctrl_right.offsetWidth) <= room) {
                break;
            }
            document.body.classList.add(trim_steps[i]);
            room = Math.floor((window.innerWidth - ctrl_center.offsetWidth) / 2) - 10;
        }

        // Equal side widths keep the centered block optically centered, but only apply them
        // when they still fit next to it.
        const min_width = Math.max(235, ctrl_right.offsetWidth) + 25;
        if (min_width > room) {
            return;
        }
        ctrl_left.style.width = min_width + 'px';
        ctrl_left.style.minWidth = min_width + 'px';
        ctrl_right.style.width = min_width + 'px';
        ctrl_right.style.minWidth = min_width + 'px';
    }
