    /**
     * Fill a BCM-style radiogroup with saved minitool payment methods (same cards as buy-credits modal).
     * Optional first row: "latest saved" (clears preferred row via minitool-preferred-pm when chosen).
     *
     * @param {string} listId - id of the .bcm-pm-list container
     * @param {{ latestRowTitle?: string, latestRowSub?: string, noCardsHtml?: string }} [opts]
     * @param {function()} [done]
     */
    window.taaftPopulateMinitoolPmChooser = function(listId, opts, done) {
        opts = opts || {};
        var list = by_id(listId);
        if (!list || typeof xhr_get !== 'function') {
            if (typeof done === 'function') {
                done();
            }
            return;
        }
        if (list.dataset.taaftPmClickBound !== '1') {
            list.dataset.taaftPmClickBound = '1';
            list.addEventListener('click', function(e) {
                var card = e.target.closest('.bcm-pm-card');
                if (!card || !list.contains(card)) {
                    return;
                }
                var cards = list.querySelectorAll('.bcm-pm-card');
                for (var j = 0; j < cards.length; j++) {
                    cards[j].classList.remove('bcm-pm-card--selected');
                    cards[j].setAttribute('aria-checked', 'false');
                }
                card.classList.add('bcm-pm-card--selected');
                card.setAttribute('aria-checked', 'true');
                var postId = card.dataset.catmLatest === '1' ? '0' : (card.dataset.pmRowId || '0');
                if (typeof xhr_post === 'function') {
                    xhr_post('/api/minitool-preferred-pm/', 'pm_row_id=' + encodeURIComponent(postId));
                }
                if (typeof window._taaftOnCatmPmSelect === 'function') {
                    window._taaftOnCatmPmSelect();
                }
            });
        }
        xhr_get('/api/payment-methods/', function(txt) {
            try {
                var d = JSON.parse(txt);
                if (!d || d.status !== 'success' || !Array.isArray(d.payment_methods)) {
                    return;
                }
                var methods = d.payment_methods;
                var pref = d.preferred_pm_row_id;
                var prefStr = (pref !== null && pref !== undefined && String(pref) !== '' && String(pref) !== '0') ? String(pref) : '';
                list.innerHTML = '';

                if (methods.length === 0) {
                    if (opts.noCardsHtml) {
                        list.innerHTML = opts.noCardsHtml;
                    }
                    return;
                }

                var prefOk = false;
                if (prefStr) {
                    for (var si = 0; si < methods.length; si++) {
                        if (String(methods[si].id) === prefStr) {
                            prefOk = true;
                            break;
                        }
                    }
                }
                var latestSelected = !prefStr || !prefOk;

                function catmAppendCard(rowId, iconInner, titleEsc, secondLineHtml, selected, iconClassExtra) {
                    var ice = iconClassExtra ? (' ' + iconClassExtra) : '';
                    var btn = document.createElement('button');
                    btn.type = 'button';
                    btn.className = 'bcm-pm-card' + (selected ? ' bcm-pm-card--selected' : '');
                    btn.setAttribute('role', 'radio');
                    btn.setAttribute('aria-checked', selected ? 'true' : 'false');
                    if (rowId === '') {
                        btn.dataset.pmRowId = '';
                        btn.dataset.catmLatest = '1';
                    } else {
                        btn.dataset.pmRowId = rowId;
                    }
                    btn.innerHTML = '<span class="bcm-pm-card-icon' + ice + '" aria-hidden="true">' + iconInner + '</span>'
                        + '<span class="bcm-pm-card-text"><span class="bcm-pm-card-title">' + titleEsc + '</span>' + secondLineHtml + '</span>';
                    list.appendChild(btn);
                }

                var latestTitle = htmlspecialchars(String(opts.latestRowTitle || 'Latest saved card'));
                var latestSub = opts.latestRowSub ? String(opts.latestRowSub) : '';
                var latestSecond = latestSub
                    ? ('<span class="bcm-pm-card-meta"><span class="bcm-pm-card-sub">' + htmlspecialchars(latestSub) + '</span></span>')
                    : '<span class="bcm-pm-card-meta"></span>';
                catmAppendCard('', _bcmPmBrandIconSvg(''), latestTitle, latestSecond, latestSelected, 'bcm-pm-card-icon--brand');

                for (var i = 0; i < methods.length; i++) {
                    var pm = methods[i];
                    var brand = (pm.brand || 'card').toString().toUpperCase();
                    var lastRaw = (pm.last4 || '').toString().replace(/\D/g, '');
                    var last4 = lastRaw.length >= 4 ? lastRaw.slice(-4) : '';
                    var pan = last4.length >= 4 ? ('**** **** **** ' + last4) : '**** **** **** ????';
                    var sel = !!(prefStr && prefOk && String(pm.id) === prefStr);
                    var expFmt = _bcmPmFormatExpiry(pm.exp_month, pm.exp_year);
                    var expSpan = '';
                    if (expFmt !== '') {
                        if (typeof intl === 'function') {
                            expSpan = '<span class="bcm-pm-card-exp">' + htmlspecialchars(intl('Expires {exp}', {
                                values: { exp: expFmt },
                                context: 'Buy credits modal: saved card expiry date in listing',
                            })) + '</span>';
                        } else {
                            expSpan = '<span class="bcm-pm-card-exp">' + htmlspecialchars('Expires ' + expFmt) + '</span>';
                        }
                    }
                    var secondLine = '<span class="bcm-pm-card-meta"><span class="bcm-pm-card-pan">' + htmlspecialchars(pan) + '</span>' + expSpan + '</span>';
                    catmAppendCard(String(pm.id),
                        _bcmPmBrandIconSvg(pm.brand),
                        htmlspecialchars(brand),
                        secondLine,
                        sel,
                        'bcm-pm-card-icon--brand');
                }
            } catch (e) {}
            finally {
                if (typeof done === 'function') {
                    done();
                }
            }
        });
    };

