    function _bcmInit() {
        var bcm_modal = by_id('buy_credits_modal');
        if (!bcm_modal) return;
        var bcm_input = by_id('bcm_credits_input');
        var bcm_price = by_id('bcm_price_display');
        var bcm_bonus = by_id('bcm_bonus_display');
        var bcm_total_credits = by_id('bcm_total_credits_display');
        var bcm_slider = by_id('bcm_credits_slider');
        var bcm_pkg_slot = by_id('bcm_packages');
        var bcm_more_btn = by_id('bcm_packages_more_btn');
        var bcm_buy_btn = by_id('bcm_buy_btn');
        var bcm_error = by_id('bcm_custom_error');
        var bcm_status = by_id('bcm_payment_status');
        var bcm_content = bcm_modal.querySelector('.modal-content');
        var _utBcm = window._minitoolUserTopup || {};
        var BCM_MIN = _utBcm.customMin || 5000;
        var BCM_MAX = _utBcm.customMax || 400000;
        var BCM_STEP = _utBcm.customStep || 1000;
        var BCM_DEFAULT_PAID = (typeof _utBcm.defaultPaidCredits === 'number') ? _utBcm.defaultPaidCredits : 20000;
        var bcm_pkg_page = 0;

        function bcm_list_packages() {
            return bcm_pkg_slot ? bcm_pkg_slot.querySelectorAll('.bcm-package') : [];
        }

        function bcm_update_slider_fill() {
            if (!bcm_slider) {
                return;
            }
            var min = parseInt(bcm_slider.min, 10) || 0;
            var max = parseInt(bcm_slider.max, 10) || 1;
            var val = parseInt(bcm_slider.value, 10) || 0;
            var pct = max <= min ? 0 : ((val - min) / (max - min)) * 100;
            bcm_slider.style.setProperty('--bcm-fill', pct + '%');
            bcm_slider.setAttribute('aria-valuenow', String(val));
        }

        function bcm_slider_set_paid(paid) {
            if (!bcm_slider) {
                return;
            }
            var v = parseInt(paid, 10);
            if (!isFinite(v)) {
                return;
            }
            v = Math.ceil(v / BCM_STEP) * BCM_STEP;
            if (v < BCM_MIN) {
                v = BCM_MIN;
            }
            if (v > BCM_MAX) {
                v = BCM_MAX;
            }
            bcm_slider.value = String(v);
            bcm_update_slider_fill();
        }

        function bcm_resync_selection_from_paid(paid) {
            var pkgs = bcm_list_packages();
            var hit = null;
            var i;
            for (i = 0; i < pkgs.length; i++) {
                var p = parseInt(pkgs[i].dataset.credits, 10);
                if (p === paid) {
                    hit = pkgs[i];
                    break;
                }
            }
            window._bcmSelectedTopupPreset = '';
            for (i = 0; i < pkgs.length; i++) {
                var q = pkgs[i];
                if (q === hit) {
                    q.classList.add('selected');
                    window._bcmSelectedTopupPreset = q.dataset.topupPreset || '';
                } else {
                    q.classList.remove('selected');
                }
            }
        }

        function bcm_render_packages_page(nextPage) {
            if (!bcm_pkg_slot) {
                return;
            }
            bcm_pkg_slot.classList.remove('bcm-packages--fade-steady', 'bcm-packages--fade-in');
            bcm_pkg_slot.classList.add('bcm-packages--fade-out');
            window.setTimeout(function() {
                bcm_pkg_slot.innerHTML = _bcmBuildTopupPackagesHtml(nextPage);
                bcm_pkg_slot.classList.remove('bcm-packages--fade-out');
                bcm_pkg_slot.classList.add('bcm-packages--fade-in');
                _bcmFillPackageGenEstimates(bcm_pkg_slot);
                var paidNow = bcm_effective_paid_credits();
                if (!isFinite(paidNow) || paidNow <= 0) {
                    paidNow = BCM_DEFAULT_PAID;
                }
                bcm_resync_selection_from_paid(paidNow);
                bcm_update_price();
                window.setTimeout(function() {
                    bcm_pkg_slot.classList.remove('bcm-packages--fade-in');
                    bcm_pkg_slot.classList.add('bcm-packages--fade-steady');
                }, 320);
            }, 150);
        }

        if (!bcm_buy_btn.dataset.bcmLabelDefault) {
            bcm_buy_btn.dataset.bcmLabelDefault = bcm_buy_btn.textContent;
        }

        function bcm_clear_payment_status_on_edit() {
            if (bcm_buy_btn.classList.contains('bcm-buy-btn--loading')) {
                return;
            }
            _bcmCancelSuccessAutoclose();
            if (bcm_status && !bcm_status.hidden) {
                bcm_status.hidden = true;
                bcm_status.innerHTML = '';
                bcm_status.className = 'bcm-payment-status';
            }
        }

        function bcm_set_purchase_ui(pending, statusHtml, statusKind) {
            if (pending) {
                _bcmCancelSuccessAutoclose();
            }
            if (bcm_content) {
                bcm_content.classList.toggle('bcm-purchase-pending', !!pending);
            }
            if (pending) {
                bcm_buy_btn.disabled = true;
                bcm_buy_btn.classList.add('bcm-buy-btn--loading');
                bcm_buy_btn.setAttribute('aria-busy', 'true');
                bcm_buy_btn.textContent = _bcmFlowIntl('buyButtonWorking');
            } else {
                bcm_buy_btn.classList.remove('bcm-buy-btn--loading');
                bcm_buy_btn.removeAttribute('aria-busy');
                if (typeof _bcmSetFooterMainMode === 'function') {
                    _bcmSetFooterMainMode();
                } else {
