    /**
     * Update all credits displays on the page and persist to localStorage.
     * Call this after any action that changes the user's credit balance.
     * @param {number} newCredits — the new credits balance
     */
    window.updateCreditsDisplay = function(newCredits) {
        var c = parseInt(newCredits) || 0;
        USER.minitool_credits = c;
        localstorage_update({ minitool_credits: c });
        query('[data-credits-display]').forEach(function(el) {
            el.innerHTML = '<svg class="cu_coin_icon" viewBox="0 0 24 24" width="14" height="14"><circle cx="12" cy="12" r="10" fill="#f9c74f" stroke="#c89b3c" stroke-width="1.5"/><text x="12" y="16.5" text-anchor="middle" font-size="13" font-weight="700" fill="#7a5c1e" font-family="Arial,sans-serif">C</text></svg> ' + format_credits_compact(c);
            el.classList.remove('credits-updated-flash');
            void el.offsetWidth;
            el.classList.add('credits-updated-flash');
        });
        query('[data-credits="available"]').forEach(function(el) {
            el.innerText = format_credits_compact(c);
            el.classList.remove('credits-updated-flash');
            void el.offsetWidth;
            el.classList.add('credits-updated-flash');
        });
    };

    window.addEventListener('pageshow', function(e) {
        if (!e.persisted) return;
        try {
            if (typeof hideModal === 'function') {
                hideModal('payment_status');
            }
        } catch (eBf) {}
    });

