(function () {
    var el = document.getElementById('ctrl_install');
    if (!el) {
        return;
    }
    // The install page keeps this control and marks it active in its own CSS, the way
    // dashboard.php does for .dashboard_link, so there is no path check here.
    function hide_ctrl_install() {
        window.taaftPwaInstalledOnDevice = true;
        el.classList.add('hidden');
        document.body.classList.remove('home_install_available');
        document.body.classList.remove('ctrl_install_compact');
    }
    function reveal_ctrl_install() {
        if (window.taaftPwaInstalledOnDevice) {
            return;
        }
        el.classList.remove('hidden');
        schedule_fit_ctrl_install();
    }
    if (typeof isInstalledPwa === 'function' && isInstalledPwa()) {
        hide_ctrl_install();
        return;
    }

    function schedule_fit_ctrl_install() {
        if (typeof oRAF === 'function') {
            oRAF(fit_ctrl_install);
            return;
        }
        requestAnimationFrame(fit_ctrl_install);
    }
    function fit_ctrl_install() {
        var center = document.getElementById('ctrl_center');
        var right = document.getElementById('ctrl_right');
        if (!center || !right) {
            return;
        }
        if (center.classList.contains('cmdk')) {
            return;
        }
        document.body.classList.remove('ctrl_install_compact');
        if (el.classList.contains('hidden')) {
            return;
        }
        // Search is display:none below 500px; half-viewport room would be wrong there.
        if (!center.offsetWidth) {
            return;
        }
        var room = Math.floor((window.innerWidth - center.offsetWidth) / 2) - 10;
        if (right.offsetWidth > room) {
            document.body.classList.add('ctrl_install_compact');
        }
    }
    if (typeof navigator.getInstalledRelatedApps === 'function') {
        navigator.getInstalledRelatedApps().then(function (apps) {
            if (apps && apps.length) {
                hide_ctrl_install();
                return;
            }
            reveal_ctrl_install();
        }).catch(function () {
            reveal_ctrl_install();
        });
    } else {
        reveal_ctrl_install();
    }
    window.addEventListener('appinstalled', function () {
        hide_ctrl_install();
        schedule_fit_ctrl_install();
    });
    if (typeof fit_ctrl_bar === 'function') {
        var orig_fit_ctrl_bar = fit_ctrl_bar;
        fit_ctrl_bar = function () {
            fit_ctrl_install();
            orig_fit_ctrl_bar.apply(this, arguments);
        };
    }
    window.addEventListener('resize', schedule_fit_ctrl_install);
    schedule_fit_ctrl_install();
})();


(function () {
    var nav = by_id('ctrl_nav');
    var btn = by_id('ctrl_nav_btn');
    var dd = by_id('ctrl_nav_dropdown');
    if (!nav || !btn || !dd) {
        return;
    }

    // Results list caps at 280px; hover-close uses this as a virtual hit height so
    // shrinking the tree under the cursor does not count as leaving the menu.
    var RESULTS_MAX_HEIGHT = 280;
    var hoverMql = window.matchMedia('(hover: hover) and (pointer: fine)');
    var hoverCloseTimer = null;
    var virtualHoverWatching = false;

    function clearHoverCloseTimer() {
        clearTimeout(hoverCloseTimer);
        hoverCloseTimer = null;
    }

    function getVirtualNavBounds() {
        var navRect = nav.getBoundingClientRect();
        var ddRect = dd.getBoundingClientRect();
        var resultsEl = dd.querySelector('.listing-task-filter-results');
        var bottom = Math.max(navRect.bottom, ddRect.bottom);
        if (resultsEl && !dd.classList.contains('hidden')) {
            var resultsRect = resultsEl.getBoundingClientRect();
            var chrome = Math.max(0, ddRect.height - resultsRect.height);
            bottom = Math.max(bottom, ddRect.top + chrome + RESULTS_MAX_HEIGHT);
        }
        return {
            left: Math.min(navRect.left, ddRect.left),
            right: Math.max(navRect.right, ddRect.right),
            top: Math.min(navRect.top, ddRect.top),
            bottom: bottom,
        };
    }

    function pointInVirtualNav(x, y) {
        var b = getVirtualNavBounds();
        return x >= b.left && x <= b.right && y >= b.top && y <= b.bottom;
    }

    function stopVirtualHoverWatch() {
        if (!virtualHoverWatching) {
            return;
        }
        virtualHoverWatching = false;
        document.removeEventListener('pointermove', onVirtualHoverMove, true);
    }

    function onVirtualHoverMove(e) {
        if (dd.classList.contains('hidden')) {
            stopVirtualHoverWatch();
            return;
        }
        if (nav.contains(e.target)) {
            clearHoverCloseTimer();
            stopVirtualHoverWatch();
            return;
        }
        if (pointInVirtualNav(e.clientX, e.clientY)) {
            clearHoverCloseTimer();
            return;
        }
        stopVirtualHoverWatch();
        hoverCloseTimer = setTimeout(closeNav, 150);
    }

    function startVirtualHoverWatch() {
        if (virtualHoverWatching) {
            return;
        }
        virtualHoverWatching = true;
        document.addEventListener('pointermove', onVirtualHoverMove, true);
    }

    function closeNav() {
        stopVirtualHoverWatch();
        clearHoverCloseTimer();
        dd.classList.add('hidden');
        nav.classList.remove('open');
        btn.setAttribute('aria-expanded', 'false');
        document.dispatchEvent(new CustomEvent('ctrl-task-tree-close'));
    }
    function openNav() {
        var wasHidden = dd.classList.contains('hidden');
        dd.classList.remove('hidden');
        nav.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
        // Only reset/load the tree on a real closed→open transition. Re-entering
        // from the virtual hover footprint must not wipe the current drill path.
        if (wasHidden) {
            document.dispatchEvent(new CustomEvent('ctrl-task-tree-open'));
        }
    }
    btn.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (dd.classList.contains('hidden')) {
            openNav();
        } else {
            closeNav();
        }
    });
    nav.addEventListener('mouseenter', function () {
        if (!hoverMql.matches) {
            return;
        }
        stopVirtualHoverWatch();
        clearHoverCloseTimer();
        openNav();
    });
    nav.addEventListener('mouseleave', function (e) {
        if (!hoverMql.matches) {
            return;
        }
        // Content shrink can leave the pointer outside the painted box but still
        // inside the max-height footprint — keep open and watch until it leaves that.
        if (pointInVirtualNav(e.clientX, e.clientY)) {
            clearHoverCloseTimer();
            startVirtualHoverWatch();
            return;
        }
        hoverCloseTimer = setTimeout(closeNav, 150);
    });
    dd.addEventListener('mouseenter', function () {
        if (!hoverMql.matches) {
            return;
        }
        stopVirtualHoverWatch();
        clearHoverCloseTimer();
    });
    // Content reflow can shrink the painted box under the cursor. Cancel any
    // pending close and watch the max-height footprint until the pointer leaves it.
    document.addEventListener('ctrl-task-tree-content-change', function () {
        clearHoverCloseTimer();
        if (!hoverMql.matches || dd.classList.contains('hidden')) {
            return;
        }
        startVirtualHoverWatch();
    });
    document.addEventListener('click', function (e) {
        if (!nav.contains(e.target)) {
            closeNav();
        }
    });
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') {
            closeNav();
        }
    });
    dd.addEventListener('click', function (e) {
        if (e.target.closest('a')) {
            closeNav();
        }
    });
})();

(function () {
    var picker = by_id('ctrl-task-tree-picker');
    if (!picker) {
        return;
    }

    var search = picker.querySelector('[data-task-tree-search]');
    var results = picker.querySelector('[data-task-tree-results]');
    var back = picker.querySelector('[data-task-tree-back]');
    var breadcrumb = picker.querySelector('[data-task-tree-breadcrumb]');
    var path = [];
    var treeSeq = 0;
    var treeCache = {};
    var treeRequests = {};
    var suggestSeq = 0;
    var suggestTimer = null;
    var labels = {
        root: "All tasks",
        loading: "Loading tasks...",
        empty: "No matching tasks found.",
        children: "Open sub-tasks",
        treeEmpty: "No tasks with tools here yet.",
    };

    function notifyContentChange() {
        document.dispatchEvent(new CustomEvent('ctrl-task-tree-content-change'));
    }

    function setLoading(isLoading) {
        results.classList.toggle('is-loading', !!isLoading);
        if (isLoading) {
            results.setAttribute('aria-busy', 'true');
            results.setAttribute('data-loading-label', labels.loading);
        } else {
            results.removeAttribute('aria-busy');
        }
        notifyContentChange();
    }

    function updateNav() {
        breadcrumb.innerHTML = '';
        back.classList.toggle('visible', path.length > 0);
        if (!path.length) {
            return;
        }

        var rootBtn = document.createElement('button');
        rootBtn.type = 'button';
        rootBtn.className = 'listing-task-tree-breadcrumb-btn';
        rootBtn.dataset.taskTreeDepth = '-1';
        rootBtn.textContent = labels.root;
        breadcrumb.appendChild(rootBtn);

        path.forEach(function (part, index) {
            var sep = document.createElement('span');
            sep.className = 'listing-task-tree-breadcrumb-sep';
            sep.setAttribute('aria-hidden', 'true');
            sep.textContent = '/';
            breadcrumb.appendChild(sep);

            var partBtn = document.createElement('button');
            partBtn.type = 'button';
            partBtn.className = 'listing-task-tree-breadcrumb-btn';
            partBtn.dataset.taskTreeDepth = String(index);
            partBtn.textContent = (part.name || '').trim();
            if (index === path.length - 1) {
                partBtn.classList.add('current');
                partBtn.disabled = true;
                partBtn.setAttribute('aria-current', 'page');
            }
            breadcrumb.appendChild(partBtn);
        });
    }

    function taskButton(task) {
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'listing-country-filter-item listing-task-filter-item';
        btn.setAttribute('role', 'option');
        btn.dataset.taskTreeTaskId = String(parseInt(task && task.id, 10) || 0);
        btn.dataset.taskTreeTaskName = task && task.name ? String(task.name) : '';
        btn.dataset.taskTreeTaskSlug = task && task.slug ? String(task.slug) : '';

        var emoji = task && task.emojis ? String(task.emojis).trim() : '';
        if (emoji !== '') {
            var emojiSpan = document.createElement('span');
            emojiSpan.textContent = emoji + ' ';
            btn.appendChild(emojiSpan);
        }

        var nameSpan = document.createElement('span');
        nameSpan.textContent = task && task.name ? String(task.name) : '';
        btn.appendChild(nameSpan);
        return btn;
    }

    function renderSuggestions(tasks, query) {
        results.innerHTML = '';
        var safeTasks = Array.isArray(tasks) ? tasks : [];
        if (!safeTasks.length && String(query || '').trim() !== '') {
            var empty = document.createElement('div');
            empty.className = 'listing-task-suggest-empty';
            empty.textContent = labels.empty;
            results.appendChild(empty);
            notifyContentChange();
            return;
        }

        safeTasks.forEach(function (task) {
            if ((parseInt(task && task.id, 10) || 0) > 0) {
                results.appendChild(taskButton(task));
            }
        });
        notifyContentChange();
    }

    function renderTree(nodes) {
        results.innerHTML = '';
        var safeNodes = Array.isArray(nodes) ? nodes : [];
        if (!safeNodes.length) {
            var treeEmpty = document.createElement('div');
            treeEmpty.className = 'listing-task-suggest-empty';
            treeEmpty.textContent = labels.treeEmpty;
            results.appendChild(treeEmpty);
            notifyContentChange();
            return;
        }
        safeNodes.forEach(function (task) {
            var taskId = parseInt(task && task.id, 10) || 0;
            if (taskId <= 0) {
                return;
            }

            var row = document.createElement('div');
            row.className = 'listing-task-tree-row';
            if (!path.length) {
                row.classList.add('tree-root');
            }
            row.appendChild(taskButton(task));

            var drillBtn = document.createElement('button');
            drillBtn.type = 'button';
            drillBtn.className = 'listing-task-tree-drill';
            drillBtn.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path fill="currentColor" d="M6 3.2 10.8 8 6 12.8l-1.2-1.2L8.4 8 4.8 4.4z"/></svg>';
            if (task && task.has_children) {
                drillBtn.dataset.taskTreeParentId = String(taskId);
                drillBtn.dataset.taskTreeParentName = task.name ? String(task.name) : '';
                drillBtn.setAttribute('aria-label', labels.children + ': ' + (task.name || ''));
                drillBtn.title = labels.children;
            } else {
                drillBtn.classList.add('empty');
                drillBtn.setAttribute('aria-hidden', 'true');
                drillBtn.tabIndex = -1;
            }
            row.appendChild(drillBtn);
            results.appendChild(row);
        });
        notifyContentChange();
    }

    function appendDebugSuffix(url) {
        if (typeof debugSuffix !== 'undefined' && debugSuffix) {
            return url + debugSuffix;
        }
        return url;
    }

    function taskTreeCacheKey(parentId) {
        return String(parentId > 0 ? parentId : 0);
    }

    function requestTree(parentId) {
        var safeParentId = Number.isFinite(parentId) && parentId > 0 ? parentId : 0;
        var cacheKey = taskTreeCacheKey(safeParentId);
        if (Object.prototype.hasOwnProperty.call(treeCache, cacheKey)) {
            return Promise.resolve(treeCache[cacheKey]);
        }
        if (treeRequests[cacheKey]) {
            return treeRequests[cacheKey];
        }

        treeRequests[cacheKey] = fetch(appendDebugSuffix('/api/task-tree-navigation/?parent_id=' + encodeURIComponent(String(safeParentId))))
            .then(function (response) {
                if (response.status !== 200) {
                    return null;
                }
                return response.json();
            })
            .then(function (data) {
                if (!data || data.success !== true) {
                    return null;
                }
                var nodes = Array.isArray(data.nodes) ? data.nodes : [];
                if (nodes.length) {
                    treeCache[cacheKey] = nodes;
                }
                return nodes;
            })
            .catch(function () {
                return null;
            })
            .finally(function () {
                delete treeRequests[cacheKey];
            });

        return treeRequests[cacheKey];
    }

    async function fetchTree(parentId) {
        var safeParentId = Number.isFinite(parentId) && parentId > 0 ? parentId : 0;
        var cacheKey = taskTreeCacheKey(safeParentId);
        var seq = ++treeSeq;
        if (Object.prototype.hasOwnProperty.call(treeCache, cacheKey)) {
            renderTree(treeCache[cacheKey]);
            setLoading(false);
            return;
        }
        setLoading(true);
        try {
            var nodes = await requestTree(safeParentId);
            if (seq !== treeSeq || nodes === null) {
                return;
            }
            renderTree(nodes);
        } catch (e) {
        } finally {
            if (seq === treeSeq) {
                setLoading(false);
            }
        }
    }

    async function fetchSuggestions(query) {
        var seq = ++suggestSeq;
        try {
            var response = await fetch(appendDebugSuffix('/api/mini-tools-task-suggest/?q=' + encodeURIComponent(query)));
            if (seq !== suggestSeq || response.status !== 200) {
                return;
            }
            var data = await response.json();
            if (seq !== suggestSeq || !data || data.success !== true) {
                return;
            }
            renderSuggestions(data.tasks || [], query);
        } catch (e) {
        }
    }

    function openPicker() {
        picker.setAttribute('aria-hidden', 'false');
        path = [];
        treeSeq++;
        suggestSeq++;
        if (suggestTimer) {
            clearTimeout(suggestTimer);
            suggestTimer = null;
        }
        search.value = '';
        updateNav();
        fetchTree(0);
        setTimeout(function () {
            search.focus();
        }, 0);
    }

    function closePicker() {
        picker.setAttribute('aria-hidden', 'true');
        treeSeq++;
        suggestSeq++;
        if (suggestTimer) {
            clearTimeout(suggestTimer);
            suggestTimer = null;
        }
    }

    function drillInto(taskId, taskName) {
        var safeTaskId = parseInt(taskId, 10) || 0;
        if (safeTaskId <= 0) {
            return;
        }
        path.push({
            id: safeTaskId,
            name: String(taskName || '').trim(),
        });
        updateNav();
        fetchTree(safeTaskId);
    }

    function moveToDepth(depth) {
        var safeDepth = parseInt(String(depth), 10);
        if (Number.isNaN(safeDepth)) {
            return;
        }
        if (safeDepth < 0) {
            path = [];
            updateNav();
            fetchTree(0);
            return;
        }
        if (safeDepth >= path.length) {
            return;
        }
        path = path.slice(0, safeDepth + 1);
        updateNav();
        fetchTree(parseInt(path[safeDepth].id, 10) || 0);
    }

    function focusItem(index) {
        var items = Array.from(results.querySelectorAll('[data-task-tree-task-id]'));
        if (!items.length) {
            return;
        }
        var safeIndex = Math.max(0, Math.min(index, items.length - 1));
        items[safeIndex].focus();
    }

    search.addEventListener('input', function () {
        var query = String(search.value || '').trim();
        if (suggestTimer) {
            clearTimeout(suggestTimer);
            suggestTimer = null;
        }
        if (query === '') {
            suggestSeq++;
            fetchTree(path.length ? parseInt(path[path.length - 1].id, 10) || 0 : 0);
            return;
        }
        suggestTimer = setTimeout(function () {
            suggestTimer = null;
            fetchSuggestions(query);
        }, 200);
    });

    search.addEventListener('keydown', function (e) {
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            focusItem(0);
        }
    });

    results.addEventListener('click', function (e) {
        var drillBtn = e.target.closest('[data-task-tree-parent-id]');
        if (drillBtn && results.contains(drillBtn)) {
            e.preventDefault();
            e.stopPropagation();
            search.value = '';
            drillInto(drillBtn.dataset.taskTreeParentId || '0', drillBtn.dataset.taskTreeParentName || '');
            return;
        }

        var taskBtn = e.target.closest('[data-task-tree-task-id]');
        if (!taskBtn || !results.contains(taskBtn)) {
            return;
        }
        var taskSlug = String(taskBtn.dataset.taskTreeTaskSlug || '').trim();
        if (taskSlug === '') {
            return;
        }
