            return;
        }
        var items = Array.from(results.querySelectorAll('[data-task-tree-task-id]'));
        var index = items.indexOf(target);
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            focusItem(index + 1);
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            if (index <= 0) {
                search.focus();
            } else {
                focusItem(index - 1);
            }
        }
    });

    back.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (!path.length) {
            return;
        }
        search.value = '';
        path.pop();
        updateNav();
        fetchTree(path.length ? parseInt(path[path.length - 1].id, 10) || 0 : 0);
    });

    breadcrumb.addEventListener('click', function (e) {
        var crumb = e.target.closest('[data-task-tree-depth]');
        if (!crumb || crumb.classList.contains('current')) {
            return;
        }
        e.preventDefault();
        e.stopPropagation();
        search.value = '';
        moveToDepth(crumb.dataset.taskTreeDepth || '-1');
    });

    document.addEventListener('ctrl-task-tree-open', openPicker);
    document.addEventListener('ctrl-task-tree-close', closePicker);

    var preloadRootTree = function () {
        requestTree(0);
    };
    if (typeof window.requestIdleCallback === 'function') {
        window.requestIdleCallback(preloadRootTree, { timeout: 1500 });
    } else {
        setTimeout(preloadRootTree, 250);
    }
})();


