    // The listing-page icon reuses the object icon.
    fallbackIcons.models_page = fallbackIcons.model;

    function dragHandle() {
        var handle = document.createElement('span');
        handle.className = 'menu_item_drag_handle';
        handle.setAttribute('aria-hidden', 'true');
        return handle;
    }

    function hideToggle(menuId, label) {
        var toggle = document.createElement('span');
        toggle.className = 'menu_item_hide_toggle checked';
        toggle.setAttribute('role', 'checkbox');
        toggle.setAttribute('aria-checked', 'true');
        toggle.setAttribute('tabindex', '0');
        toggle.setAttribute('data-menu-id', menuId);
        toggle.setAttribute('aria-label', label);
        return toggle;
    }

    function removeControl(menuId) {
        var control = document.createElement('span');
        control.className = 'menu_item_remove';
        control.setAttribute('role', 'button');
        control.setAttribute('tabindex', '0');
        control.setAttribute('data-menu-id', menuId);
        control.setAttribute('aria-label', removeLabel);
        control.innerHTML = closeSvg;
        return control;
    }

    // Row identity (data-menu-id / data-menu-item) is rendered server-side in
    // the debug branch above; here we only inject the edit-mode chrome.
    // Skip rows that already have chrome: script-head may inject Dashboard
    // (with handle + toggle) before this script runs via wait_for_element.
    menuInner.querySelectorAll(':scope > a[data-menu-id]').forEach(function (row) {
        if (row.querySelector(':scope > .menu_item_drag_handle')) {
            return;
        }
        var menuId = row.getAttribute('data-menu-id');
        row.insertBefore(dragHandle(), row.firstChild);
        row.insertBefore(hideToggle(menuId, hideItemLabel), row.children[1] || null);
    });

    menuInner.querySelectorAll(':scope > .divider[data-menu-id]').forEach(function (divider) {
        if (divider.querySelector(':scope > .menu_item_drag_handle')) {
            return;
        }
        var menuId = divider.getAttribute('data-menu-id');
        divider.appendChild(dragHandle());
        divider.appendChild(hideToggle(menuId, hideDividerLabel));
    });
    var createTool = menuInner.querySelector('[data-menu-id="switch_create_tool_menu"]');
    if (createTool) {
        var finalDivider = document.createElement('div');
        finalDivider.className = 'divider';
        finalDivider.setAttribute('data-menu-id', 'divider_3');
        finalDivider.setAttribute('data-menu-item', 'true');
        finalDivider.appendChild(dragHandle());
        finalDivider.appendChild(hideToggle('divider_3', hideDividerLabel));
        createTool.insertAdjacentElement('afterend', finalDivider);
    }

    // Country pins encode ISO alpha-2 as (letter1 * 100) + letter2 (A=1).
    // Rebuild the flag emoji from that when older stored entries lack emoji.
    function countryFlagEmojiFromObjId(objId) {
        var n = parseInt(objId, 10);
        if (!n) {
            return '';
        }
        var letter1 = Math.floor(n / 100);
        var letter2 = n % 100;
        if (letter1 < 1 || letter1 > 26 || letter2 < 1 || letter2 > 26) {
            return '';
        }
        return String.fromCodePoint(0x1F1E5 + letter1, 0x1F1E5 + letter2);
    }

    // Shared with editable-menu.js's pin-search result rows (window.build_menu_pin_icon) -
    // one source of truth for "how does a pin's icon resolve," used by both the sidebar and search rows.
    window.build_menu_pin_icon = function (entry) {
        var entryEmoji = entry.emoji || '';
        if (!entryEmoji && entry.obj_type === 'country') {
            entryEmoji = countryFlagEmojiFromObjId(entry.obj_id);
        }
        var imageUrl = entry.image || '';
        // Old pins also come from browser storage, without server-side re-resolution.
        if (imageUrl && entry.obj_type === 'news_item') {
            try {
                var newsImageUrl = new URL(imageUrl);
                if (newsImageUrl.origin !== 'https://' + app_media_domain || newsImageUrl.username || newsImageUrl.password) {
                    imageUrl = '';
                }
            } catch (invalidNewsImageUrl) {
                imageUrl = '';
            }
        }
        if (imageUrl) {
            var image = document.createElement('img');
            image.className = 'custom_menu_item_icon';
            image.setAttribute('src', imageUrl);
            image.setAttribute('alt', '');
            image.setAttribute('loading', 'lazy');
            return image;
        }
        if (entryEmoji) {
            // Use <div>, not <span>: collapsed menu hides label spans via
            // opacity 0.001; a span emoji would disappear with the label.
            var emoji = document.createElement('div');
            emoji.className = 'custom_menu_item_icon custom_menu_item_emoji';
            emoji.setAttribute('aria-hidden', 'true');
            emoji.textContent = entryEmoji;
            return emoji;
        }
        var iconWrap = document.createElement('div');
        iconWrap.innerHTML = fallbackIcons[entry.obj_type] || fallbackIcons.default;
        if (iconWrap.firstElementChild) {
            iconWrap.firstElementChild.classList.add('custom_menu_item_icon');
            return iconWrap.firstElementChild;
        }
        return null;
    };

    window.build_custom_menu_item = function (menuId, entry) {
        if (!entry) {
            return null;
        }
        if (entry.type === 'divider') {
            var divider = document.createElement('div');
            divider.className = 'divider custom_divider';
            divider.setAttribute('data-menu-id', menuId);
            divider.setAttribute('data-menu-item', 'true');
            divider.appendChild(dragHandle());
            divider.appendChild(removeControl(menuId));
            return divider;
        }
        var row = document.createElement('a');
        row.className = 'menu_item custom_menu_item';
        row.setAttribute('data-menu-id', menuId);
        row.setAttribute('data-menu-item', 'true');
        row.setAttribute('href', entry.path && typeof appUrl === 'function' ? appUrl(entry.path) : (entry.path || '#'));
        row.appendChild(dragHandle());
        var icon = window.build_menu_pin_icon(entry);
        if (icon) {
            row.appendChild(icon);
        }
        var fullTitle = entry.title || '';
        // Keep stored/full title for tooltips; clip the visible label so long
        // repo/paper names don't wrap inside the fixed-height menu row.
        var MENU_LABEL_MAX_CHARS = 28;
        var labelText = fullTitle;
        if (fullTitle.length > MENU_LABEL_MAX_CHARS) {
            labelText = fullTitle.slice(0, MENU_LABEL_MAX_CHARS - 3) + '...';
        }
        var label = document.createElement('span');
        label.textContent = labelText;
        if (fullTitle) {
            row.setAttribute('title', fullTitle);
        }
        row.appendChild(label);
        row.appendChild(removeControl(menuId));
        return row;
    };

    window.apply_menu_layout = function (layout) {
        var order = layout && layout.order && layout.order.length ? layout.order : MENU_DEFAULT_ORDER;
        var hidden = layout && layout.hidden ? layout.hidden : [];
        var customItems = layout && layout.custom_items ? layout.custom_items : {};
        // Always rebuild custom rows so server-enriched fields (e.g. country
        // flag emoji) replace optimistic placeholder icons like the globe.
        menuInner.querySelectorAll('.custom_menu_item, .custom_divider').forEach(function (row) {
            row.remove();
        });
        order.forEach(function (menuId) {
            var row = menuInner.querySelector('[data-menu-id="' + menuId + '"]');
            if (!row && menuId.indexOf('custom_') === 0 && customItems[menuId]) {
                row = window.build_custom_menu_item(menuId, customItems[menuId]);
            }
            if (row) {
                menuInner.appendChild(row);
            }
        });
        if (order.indexOf('switch_dashboard') === -1) {
            var dashboard = menuInner.querySelector('[data-menu-id="switch_dashboard"]');
            var home = menuInner.querySelector('[data-menu-id="switch_hist_menu"]');
            if (dashboard && home) {
                home.insertAdjacentElement('afterend', dashboard);
            }
        }
        MENU_DEFAULT_ORDER.forEach(function (menuId) {
            var row = menuInner.querySelector('[data-menu-id="' + menuId + '"]');
            if (!row) {
                return;
            }
            var isHidden = hidden.indexOf(menuId) > -1;
            row.classList.toggle('hidden_menu_item', isHidden);
            var toggle = row.querySelector('.menu_item_hide_toggle[data-menu-id="' + menuId + '"]');
            if (toggle) {
                toggle.classList.toggle('checked', !isHidden);
                toggle.setAttribute('aria-checked', isHidden ? 'false' : 'true');
            }
        });
    };

    try {
        // Prefer live USER.id — page cache often bakes MENU_LAYOUT_USER_ID=0.
        var menuLayoutUserId = (window.USER && parseInt(window.USER.id, 10)) || parseInt(window.MENU_LAYOUT_USER_ID, 10) || 0;
        var storageKey = typeof window.menu_layout_storage_key === 'function'
            ? window.menu_layout_storage_key(menuLayoutUserId)
            : '';
        var storedEnvelope = storageKey ? localStorage.getItem(storageKey) : null;
        if (storedEnvelope) {
            var envelope = JSON.parse(storedEnvelope);
            if (envelope && Object.prototype.hasOwnProperty.call(envelope, 'layout')) {
                window.apply_menu_layout(envelope.layout);
            }
        }
    } catch (e) {
        console.log('[menu pins] cached menu bootstrap failed:', e);
    }
})();









